ALTER TABLE tasks ADD completed_at DATETIME NULL, ADD completed_by CHAR(32) NULL, ADD cancelled_at DATETIME NULL, ADD cancelled_by CHAR(32) NULL, ADD cancellation_reason VARCHAR(255) NULL, ADD FOREIGN KEY(completed_by) REFERENCES users(id), ADD FOREIGN KEY(cancelled_by) REFERENCES users(id), ADD INDEX(assigned_to,due_at,status);
CREATE TABLE calendar_events (id CHAR(32) PRIMARY KEY,opportunity_id CHAR(32) NULL,responsible_id CHAR(32) NOT NULL,title VARCHAR(180) NOT NULL,event_type VARCHAR(50) NOT NULL DEFAULT 'commitment',starts_at DATETIME NOT NULL,ends_at DATETIME NULL,status ENUM('scheduled','done','cancelled') NOT NULL DEFAULT 'scheduled',notes TEXT NULL,created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,FOREIGN KEY(responsible_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(responsible_id,starts_at,status));
CREATE TABLE notifications (id CHAR(32) PRIMARY KEY,user_id CHAR(32) NOT NULL,event_key VARCHAR(190) NOT NULL,title VARCHAR(180) NOT NULL,message VARCHAR(500) NOT NULL,entity_type VARCHAR(50) NULL,entity_id CHAR(32) NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE(user_id,event_key),INDEX(user_id,read_at,created_at));
CREATE TABLE documents (id CHAR(32) PRIMARY KEY,opportunity_id CHAR(32) NOT NULL,entity_type ENUM('contact','opportunity','proposal','contract') NOT NULL,entity_id CHAR(32) NOT NULL,uploaded_by CHAR(32) NOT NULL,original_name VARCHAR(255) NOT NULL,storage_name CHAR(64) NOT NULL UNIQUE,mime_type VARCHAR(100) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,deleted_at DATETIME NULL,deleted_by CHAR(32) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id),FOREIGN KEY(deleted_by) REFERENCES users(id),INDEX(opportunity_id,deleted_at));
CREATE TABLE audit_events (id CHAR(32) PRIMARY KEY,user_id CHAR(32) NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id CHAR(32) NOT NULL,summary VARCHAR(500) NOT NULL,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(created_at),INDEX(entity_type,entity_id));
